(4703417, 675607, 31727, '<td valign="top">I did this shoot in Hawiie for American Airline .You could have popt her with a strobe.Great shoot.Harvey Sherman mrhsherman@yahoo.com.</td>', 'I did this shoot in Hawiie for American Airline .You could have popt her with a strobe.Great shoot.Harvey Sherman mrhsherman@yahoo.com.', '2008-05-15 01:12:39.000000', NULL, 0),
